-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.evoker.augmentation.Name"] = "Icy Veins"
L["rm.retail.evoker.augmentation.Description"] = "Recomendada para Aprimoramento: a prioridade de Poder de Ébano da Icy Veins. Poder de Ébano é um dos poucos bônus que o jogo ainda mostra aos addons em combate no Midnight, então sua manutenção funciona lá. Fora de combate: Escamas Virulentas em um alvo amigável do grupo que não as tenha, Chama Viva em um inimigo. Depois, Poder de Ébano quando ausente ou abaixo de 4 segundos, e assim que sair do tempo de recarga, a menos que Sopro Eônico esteja pronto; Presciência; Sopro de Fogo; Revolta; Erupção durante Poder de Ébano ou com dois Estouros de Essência; Ataque Lazúli; Chama Viva. Bônus ocultos só pulam o próprio passo em combate. Lembretes: Sopro Eônico e Respiração Profunda (você mira), Jogo Virado com Sopro de Fogo pronto, Salto temporal com Sopro de Fogo e Revolta ambos em recarga, além dos lembretes utilitários. Presciência e Escamas Virulentas vão no seu alvo: escolher o aliado, e o nível de potencialização, fica a seu critério."
L["rm.retail.evoker.augmentation.assisted.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.evoker.augmentation.assisted.Description"] = "A sugestão do Assistente de Combate da Blizzard para Aprimoramento, uma alternativa à rotação integrada de Aprimoramento da Icy Veins recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Ela só relança Poder de Ébano depois que ele expira, e aguarda enquanto você lança ou segura um feitiço potencializado. Lembretes em combate para Sopro Eônico, Respiração Profunda, Jogo Virado e Salto temporal, além de Supressão, Escamas de Obsidiana, Bênção do Bronze e Fonte de Magia, como nas outras rotações integradas de Conjurante."
L["rm.retail.evoker.devastation.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.evoker.devastation.Description"] = "Recomendada para Devastação. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança, canaliza Desintegrar ou segura um feitiço potencializado. Escolher o nível de potencialização fica a seu critério. Junto a isso, lembretes em combate para Raiva Dragônica, Respiração Profunda e Jogo Virado, Supressão em um lançamento interrompível e Escamas de Obsidiana sempre que estiver pronta e, fora de combate, Bênção do Bronze quando estiver ausente e Fonte de Magia em um alvo amigável do seu grupo. Lançamentos inimigos ficam ocultos em combate, então Supressão só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar Escamas de Obsidiana é com você."
L["rm.retail.evoker.devastation.guide.Name"] = "Referência (SimulationCraft e Icy Veins)"
L["rm.retail.evoker.devastation.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade ideal de Devastação. Ativações, tempos de recarga e a queimadura no alvo ficam ocultos em combate no Midnight, então ela não pode funcionar lá; leia-a ou duplique-a para experimentar. Puxa com Chama Viva. Comandante-de-escama (com Desintegração em Massa aprendida): Surto da Eternidade, Sopro de Fogo, Respiração Profunda contra dois ou mais inimigos, Desintegrar com cargas de Desintegração em Massa, Pira contra cinco ou mais, Desintegrar, Chama Viva com Combustão e Chamas Saltantes, Chama Livre abaixo de dois Estouros de Essência, Meneio Lazúli. Moldachamas: Surto da Eternidade, Sopro de Fogo quando a queimadura estiver ausente ou acabando, Pira contra cinco ou mais, Desintegrar, Respiração Profunda contra quatro ou mais, Chama Livre, Chama Viva com Combustão e Chamas Saltantes, Meneio Lazúli. Depois, Ataque Lazúli em movimento, Chama Viva, Ataque Lazúli. Use as potencializações no nível 1 contra um alvo (Icy Veins). Lembretes: Raiva Dragônica, Jogo Virado durante Raiva Dragônica ou com Sopro de Fogo pronto, Respiração Profunda para Comandante-de-escama, além dos lembretes utilitários."
L["rm.retail.evoker.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.evoker.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Conjurante). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Conjurante compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.evoker.preservation.Name"] = "Referência (Icy Veins)"
L["rm.retail.evoker.preservation.Description"] = "Apenas referência, desativada por padrão. A vida dos aliados, Eco, Reversão, Estouro de Essência e todos os tempos de recarga ficam ocultos para addons em combate no Midnight, o Rotation Master não consegue escolher quem curar e a Blizzard não tem rotação do Assistente de Combate para curadores, então esta rotação integrada não cura. Ela lembra você de Bênção do Bronze e Fonte de Magia fora de combate e, quando seu alvo é um inimigo, sugere dano: Sopro de Fogo, Desintegrar, Chama Viva e Ataque Lazúli em movimento. Lembretes de Supressão e Escamas de Obsidiana como nas outras rotações integradas de Conjurante. A cura fica com você."
